import { StorageError, isStorageError } from './supabase/errors'
import { getWx, WxFileSystem } from './wx-env'

/** 和 tus-upload 的小程序单片上限一致。尾部比这更大时，不再为了避开 length 限制把剩余内容整段读入。 */
const SLICE_RETRY_LIMIT = 4 * 1024 * 1024

/**
 * 小程序本地路径的 tus `fileReader`。
 * `stat` 取长度，`readFile` 按偏移切出 `ArrayBuffer`，交给 `request.fetch` 当 body。
 */
export class WxFileReader {
  openFile(input: unknown): Promise<WxPathSource> {
    if (typeof input !== 'string' || !input) {
      return Promise.reject(new StorageError('uploadResumable in miniprogram requires a local file path'))
    }
    return statWxFileSize(input).then(size => new WxPathSource(input, size))
  }
}

export class WxPathSource {
  readonly size: number

  constructor(private readonly filePath: string, size: number) {
    this.size = size
  }

  slice(start: number, end: number): Promise<{ value: ArrayBuffer; done: boolean }> {
    const from = Math.max(0, start)
    const length = Math.max(0, end - from)
    return readWxFileSlice(this.filePath, from, length, this.size).then(value => ({
      value,
      done: end >= this.size,
    }))
  }

  close(): void {
    // 按路径切片，没有需要释放的句柄。
  }
}

export function statWxFileSize(filePath: string): Promise<number> {
  const fs = getWx()?.getFileSystemManager?.()
  if (!fs?.stat) {
    return Promise.reject(new StorageError('uploadResumable cannot stat the local file path'))
  }
  return new Promise((resolve, reject) => {
    fs.stat({
      path: filePath,
      success: (res) => {
        const size = res?.stats?.size
        if (typeof size !== 'number' || !Number.isFinite(size)) {
          reject(new StorageError('uploadResumable cannot stat the local file path'))
          return
        }
        resolve(size)
      },
      fail: () => {
        reject(new StorageError('uploadResumable cannot stat the local file path'))
      },
    })
  })
}

interface ReadRequest {
  filePath: string
  position?: number
  length?: number
}

/**
 * 读到文件末尾时不传 length。真机在 `position + length === fileSize` 时返回 1301006。
 * 从文件头一直读到末尾时连 position 也不传，代码包文件不接受这两个参数。
 */
function readWxFileSlice(filePath: string, position: number, length: number, fileSize: number): Promise<ArrayBuffer> {
  const fs = getWx()?.getFileSystemManager?.()
  if (!fs?.readFile) {
    return Promise.reject(new StorageError('uploadResumable cannot read the local file path'))
  }
  if (length <= 0) return Promise.resolve(withSliceSize(new ArrayBuffer(0)))

  const reachEnd = position + length >= fileSize
  const request: ReadRequest = { filePath }
  if (!(position === 0 && reachEnd)) {
    request.position = position
    if (!reachEnd) request.length = length
  }

  return callRead(fs, request).then(
    data => takeSlice(data, position, length, fileSize),
    error => retryRead(fs, request, position, length, fileSize, error),
  )
}

function retryRead(
  fs: WxFileSystem,
  request: ReadRequest,
  position: number,
  length: number,
  fileSize: number,
  error: unknown,
): Promise<ArrayBuffer> {
  const kind = readFailureKind(error)
  const ranged = request.position !== undefined || request.length !== undefined
  if (!kind || !ranged) return Promise.reject(readError(error))

  // 代码包只能整文件读。临时文件只在尾部很小、且是 length 越界时退回「从 position 读到末尾」。
  if (kind === 'package') {
    return callRead(fs, { filePath: request.filePath }).then(
      data => takeSlice(data, position, length, fileSize),
      fallbackError => Promise.reject(readError(fallbackError)),
    )
  }
  if (request.length === undefined || fileSize - position > SLICE_RETRY_LIMIT) {
    return Promise.reject(readError(error))
  }
  const tail: ReadRequest = position === 0 ? { filePath: request.filePath } : { filePath: request.filePath, position }
  return callRead(fs, tail).then(
    data => takeSlice(data, position, length, fileSize),
    fallbackError => Promise.reject(readError(fallbackError)),
  )
}

function callRead(fs: WxFileSystem, request: ReadRequest): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    fs.readFile?.({
      ...request,
      success: (res) => {
        if (!isArrayBuffer(res?.data)) {
          reject(new StorageError('uploadResumable cannot read the local file path'))
          return
        }
        resolve(res.data)
      },
      fail: (error) => {
        reject(error)
      },
    })
  })
}

/** 返回内容从文件头开始时要按 position 再切一刀；否则缓冲区已经从 position 开始。 */
function takeSlice(data: ArrayBuffer, position: number, length: number, fileSize: number): ArrayBuffer {
  const want = Math.min(length, Math.max(0, fileSize - position))
  const fromFileStart = position > 0 && data.byteLength === fileSize
  const start = fromFileStart ? position : 0
  if (start === 0 && data.byteLength === want) return withSliceSize(data)
  return withSliceSize(data.slice(start, start + want))
}

/**
 * tus 用 `value.size` 计算这片字节数。`Blob` 才有 `size`，`readFile` 返回的是 `ArrayBuffer`。
 * 缺了这个字段时，最后一片会被当成 0 字节。
 */
function withSliceSize(data: ArrayBuffer): ArrayBuffer {
  try {
    Object.defineProperty(data, 'size', { value: data.byteLength, configurable: true })
    return data
  } catch {
    const copy = new ArrayBuffer(data.byteLength)
    new Uint8Array(copy).set(new Uint8Array(data))
    Object.defineProperty(copy, 'size', { value: copy.byteLength })
    return copy
  }
}

/** 小程序跨上下文返回的 ArrayBuffer，`instanceof` 经常是 false。 */
function isArrayBuffer(value: unknown): value is ArrayBuffer {
  return Object.prototype.toString.call(value) === '[object ArrayBuffer]'
    && typeof (value as ArrayBuffer).byteLength === 'number'
}

function readFailureKind(error: unknown): 'package' | 'range' | null {
  if (isStorageError(error)) return null
  const detail = error as { errMsg?: unknown; errno?: unknown }
  const errno = detail?.errno
  const msg = typeof detail?.errMsg === 'string' ? detail.errMsg : ''
  if (errno === 1301004 || /package directory/i.test(msg)) return 'package'
  if (errno === 1301006 || errno === 1301009 || /out of range/i.test(msg)) return 'range'
  return null
}

function readError(error: unknown): StorageError {
  if (isStorageError(error)) return error
  const errMsg = (error as { errMsg?: unknown })?.errMsg
  const detail = typeof errMsg === 'string' && errMsg ? `: ${errMsg}` : ''
  return new StorageError(`uploadResumable cannot read the local file path${detail}`)
}
