/** 微信小程序会把 string 当本地路径读取；Web/Node 没有这层语义。 */
export interface WxMiniProgramApi {
  getFileSystemManager?: () => WxFileSystem
  setStorageSync?: (key: string, value: unknown) => void
  getStorageSync?: (key: string) => unknown
  removeStorageSync?: (key: string) => void
  getStorageInfoSync?: () => { keys?: string[] }
}

export interface WxFileSystem {
  stat?: (options: {
    path: string
    success?: (res: { stats?: { size?: number } }) => void
    fail?: (error: unknown) => void
  }) => void
  readFile?: (options: {
    filePath: string
    position?: number
    length?: number
    success?: (res: { data?: ArrayBuffer }) => void
    fail?: (error: unknown) => void
  }) => void
}

export function getWx(): WxMiniProgramApi | undefined {
  return (globalThis as { wx?: WxMiniProgramApi }).wx
}

export function isWxMiniProgramEnv(): boolean {
  return typeof getWx()?.getFileSystemManager === 'function'
}
